CREATE TABLE public.regras_comissao (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),clinica_id uuid NOT NULL REFERENCES public.clinicas(id),profissional_id uuid NOT NULL REFERENCES public.profissionais(id),procedimento_id uuid REFERENCES public.procedimentos(id),especialidade_id uuid REFERENCES public.especialidades(id),tipo_calculo text NOT NULL CHECK(tipo_calculo IN ('percentual_bruto','percentual_liquido','valor_fixo')),base_apuracao text NOT NULL DEFAULT 'recebimento' CHECK(base_apuracao IN ('recebimento','execucao')),valor numeric(12,2) NOT NULL CHECK(valor>=0),ativo boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE ON public.regras_comissao TO authenticated;GRANT ALL ON public.regras_comissao TO service_role;ALTER TABLE public.regras_comissao ENABLE ROW LEVEL SECURITY;
CREATE POLICY "regras_comissao_fin" ON public.regras_comissao FOR ALL TO authenticated USING(clinica_id=current_clinica_id() AND tem_papel('owner','admin','financeiro')) WITH CHECK(clinica_id=current_clinica_id() AND tem_papel('owner','admin','financeiro'));
CREATE POLICY "regras_comissao_proprio" ON public.regras_comissao FOR SELECT TO authenticated USING(clinica_id=current_clinica_id() AND tem_papel('dentista','esteticista') AND EXISTS(SELECT 1 FROM profissionais p WHERE p.id=profissional_id AND p.user_id=auth.uid()));
CREATE TRIGGER trg_auditar AFTER INSERT OR UPDATE OR DELETE ON public.regras_comissao FOR EACH ROW EXECUTE FUNCTION public.auditar();
CREATE INDEX regras_comissao_prof_idx ON public.regras_comissao(clinica_id,profissional_id) WHERE ativo;

CREATE TABLE public.apuracoes_comissao (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),clinica_id uuid NOT NULL REFERENCES public.clinicas(id),unidade_id uuid REFERENCES public.unidades(id),profissional_id uuid NOT NULL REFERENCES public.profissionais(id),competencia date NOT NULL,valor_bruto numeric(12,2) NOT NULL DEFAULT 0,deducoes numeric(12,2) NOT NULL DEFAULT 0,valor_comissao numeric(12,2) NOT NULL DEFAULT 0,status text NOT NULL DEFAULT 'rascunho' CHECK(status IN ('rascunho','conferido','aprovado','pago')),pagamento_id uuid REFERENCES public.financeiro_pagamentos(id),conferido_por uuid,conferido_em timestamptz,aprovado_por uuid,aprovado_em timestamptz,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(clinica_id,profissional_id,competencia));
GRANT SELECT ON public.apuracoes_comissao TO authenticated;GRANT ALL ON public.apuracoes_comissao TO service_role;ALTER TABLE public.apuracoes_comissao ENABLE ROW LEVEL SECURITY;
CREATE POLICY "apuracoes_fin" ON public.apuracoes_comissao FOR SELECT TO authenticated USING(clinica_id=current_clinica_id() AND tem_papel('owner','admin','financeiro'));
CREATE POLICY "apuracoes_proprio" ON public.apuracoes_comissao FOR SELECT TO authenticated USING(clinica_id=current_clinica_id() AND tem_papel('dentista','esteticista') AND EXISTS(SELECT 1 FROM profissionais p WHERE p.id=profissional_id AND p.user_id=auth.uid()));
CREATE TRIGGER trg_auditar AFTER INSERT OR UPDATE OR DELETE ON public.apuracoes_comissao FOR EACH ROW EXECUTE FUNCTION public.auditar();CREATE INDEX apuracoes_comissao_mes_idx ON public.apuracoes_comissao(clinica_id,competencia);

CREATE TABLE public.apuracao_comissao_itens (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),clinica_id uuid NOT NULL REFERENCES public.clinicas(id),apuracao_id uuid NOT NULL REFERENCES public.apuracoes_comissao(id),regra_id uuid REFERENCES public.regras_comissao(id),recebimento_id uuid REFERENCES public.financeiro_recebimentos(id),baixa_id uuid REFERENCES public.financeiro_baixas(id),agendamento_id uuid REFERENCES public.agendamentos(id),procedimento_id uuid REFERENCES public.procedimentos(id),descricao text NOT NULL,base_calculo numeric(12,2) NOT NULL,custo_material numeric(12,2) NOT NULL DEFAULT 0,taxa_pagamento numeric(12,2) NOT NULL DEFAULT 0,valor_comissao numeric(12,2) NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.apuracao_comissao_itens TO authenticated;GRANT ALL ON public.apuracao_comissao_itens TO service_role;ALTER TABLE public.apuracao_comissao_itens ENABLE ROW LEVEL SECURITY;
CREATE POLICY "itens_comissao_fin" ON public.apuracao_comissao_itens FOR SELECT TO authenticated USING(clinica_id=current_clinica_id() AND tem_papel('owner','admin','financeiro'));
CREATE POLICY "itens_comissao_proprio" ON public.apuracao_comissao_itens FOR SELECT TO authenticated USING(clinica_id=current_clinica_id() AND tem_papel('dentista','esteticista') AND EXISTS(SELECT 1 FROM apuracoes_comissao a JOIN profissionais p ON p.id=a.profissional_id WHERE a.id=apuracao_id AND p.user_id=auth.uid()));
CREATE TRIGGER trg_auditar AFTER INSERT OR UPDATE OR DELETE ON public.apuracao_comissao_itens FOR EACH ROW EXECUTE FUNCTION public.auditar();

CREATE TABLE public.configuracoes_fiscais (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),clinica_id uuid NOT NULL REFERENCES public.clinicas(id) UNIQUE,regime_tributario text,aliquota_impostos numeric(12,2) NOT NULL DEFAULT 0 CHECK(aliquota_impostos BETWEEN 0 AND 100),aliquota_iss numeric(12,2) NOT NULL DEFAULT 0 CHECK(aliquota_iss BETWEEN 0 AND 100),codigo_servico text,inscricao_municipal text,nfse_provider text,nfse_ativo boolean NOT NULL DEFAULT false,nfse_secret_configurado boolean NOT NULL DEFAULT false,updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE ON public.configuracoes_fiscais TO authenticated;GRANT ALL ON public.configuracoes_fiscais TO service_role;ALTER TABLE public.configuracoes_fiscais ENABLE ROW LEVEL SECURITY;
CREATE POLICY "fiscal_fin" ON public.configuracoes_fiscais FOR ALL TO authenticated USING(clinica_id=current_clinica_id() AND tem_papel('owner','admin','financeiro')) WITH CHECK(clinica_id=current_clinica_id() AND tem_papel('owner','admin','financeiro'));
CREATE TRIGGER trg_auditar AFTER INSERT OR UPDATE OR DELETE ON public.configuracoes_fiscais FOR EACH ROW EXECUTE FUNCTION public.auditar();

CREATE TABLE public.notas_fiscais_servico (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),clinica_id uuid NOT NULL REFERENCES public.clinicas(id),unidade_id uuid REFERENCES public.unidades(id),paciente_id uuid REFERENCES public.pacientes(id),recebimento_id uuid REFERENCES public.financeiro_recebimentos(id),numero text,codigo_servico text,descricao text NOT NULL,valor_servico numeric(12,2) NOT NULL CHECK(valor_servico>0),aliquota_iss numeric(12,2) NOT NULL DEFAULT 0,valor_iss numeric(12,2) NOT NULL DEFAULT 0,status text NOT NULL DEFAULT 'rascunho' CHECK(status IN ('rascunho','processando','emitida','erro','cancelada')),provider text,provider_referencia text,xml_path text,pdf_path text,mensagem_erro text,emitida_em timestamptz,created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE ON public.notas_fiscais_servico TO authenticated;GRANT ALL ON public.notas_fiscais_servico TO service_role;ALTER TABLE public.notas_fiscais_servico ENABLE ROW LEVEL SECURITY;
CREATE POLICY "nfse_fin" ON public.notas_fiscais_servico FOR ALL TO authenticated USING(clinica_id=current_clinica_id() AND tem_papel('owner','admin','financeiro')) WITH CHECK(clinica_id=current_clinica_id() AND tem_papel('owner','admin','financeiro'));
CREATE TRIGGER trg_auditar AFTER INSERT OR UPDATE OR DELETE ON public.notas_fiscais_servico FOR EACH ROW EXECUTE FUNCTION public.auditar();

CREATE TABLE public.conciliacao_importacoes (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),clinica_id uuid NOT NULL REFERENCES public.clinicas(id),conta_financeira_id uuid NOT NULL REFERENCES public.contas_financeiras(id),nome_arquivo text NOT NULL,formato text NOT NULL CHECK(formato IN ('ofx','csv')),quantidade integer NOT NULL DEFAULT 0,importado_por uuid NOT NULL DEFAULT auth.uid(),created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.conciliacao_importacoes TO authenticated;GRANT ALL ON public.conciliacao_importacoes TO service_role;ALTER TABLE public.conciliacao_importacoes ENABLE ROW LEVEL SECURITY;
CREATE POLICY "conc_import_fin" ON public.conciliacao_importacoes FOR SELECT TO authenticated USING(clinica_id=current_clinica_id() AND tem_papel('owner','admin','financeiro'));CREATE TRIGGER trg_auditar AFTER INSERT OR UPDATE OR DELETE ON public.conciliacao_importacoes FOR EACH ROW EXECUTE FUNCTION public.auditar();

CREATE TABLE public.extrato_bancario_itens (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),clinica_id uuid NOT NULL REFERENCES public.clinicas(id),importacao_id uuid NOT NULL REFERENCES public.conciliacao_importacoes(id),conta_financeira_id uuid NOT NULL REFERENCES public.contas_financeiras(id),identificador text,data date NOT NULL,descricao text NOT NULL,valor numeric(12,2) NOT NULL CHECK(valor<>0),status text NOT NULL DEFAULT 'pendente' CHECK(status IN ('pendente','conciliado','ignorado')),created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.extrato_bancario_itens TO authenticated;GRANT ALL ON public.extrato_bancario_itens TO service_role;ALTER TABLE public.extrato_bancario_itens ENABLE ROW LEVEL SECURITY;
CREATE POLICY "extrato_fin" ON public.extrato_bancario_itens FOR SELECT TO authenticated USING(clinica_id=current_clinica_id() AND tem_papel('owner','admin','financeiro'));CREATE TRIGGER trg_auditar AFTER INSERT OR UPDATE OR DELETE ON public.extrato_bancario_itens FOR EACH ROW EXECUTE FUNCTION public.auditar();CREATE UNIQUE INDEX extrato_identificador_unique ON public.extrato_bancario_itens(clinica_id,conta_financeira_id,identificador) WHERE identificador IS NOT NULL;CREATE INDEX extrato_pendente_idx ON public.extrato_bancario_itens(clinica_id,conta_financeira_id,data) WHERE status='pendente';

CREATE TABLE public.conciliacoes_bancarias (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),clinica_id uuid NOT NULL REFERENCES public.clinicas(id),extrato_item_id uuid NOT NULL UNIQUE REFERENCES public.extrato_bancario_itens(id),baixa_id uuid REFERENCES public.financeiro_baixas(id),conciliado_por uuid NOT NULL DEFAULT auth.uid(),conciliado_em timestamptz NOT NULL DEFAULT now(),observacao text);
GRANT SELECT ON public.conciliacoes_bancarias TO authenticated;GRANT ALL ON public.conciliacoes_bancarias TO service_role;ALTER TABLE public.conciliacoes_bancarias ENABLE ROW LEVEL SECURITY;
CREATE POLICY "conciliacoes_fin" ON public.conciliacoes_bancarias FOR SELECT TO authenticated USING(clinica_id=current_clinica_id() AND tem_papel('owner','admin','financeiro'));CREATE TRIGGER trg_auditar AFTER INSERT OR UPDATE OR DELETE ON public.conciliacoes_bancarias FOR EACH ROW EXECUTE FUNCTION public.auditar();